rm -f "$t"; exit $fail

arguments.new_string:
bash src/free.sh aoi >/dev/null 2>&1; [ $? = 2 ] || { echo "one argument was not rejected with exit 2"; fail=1; }
[ "$(BOOKINGS=$t bash src/free.sh aoi 2026-01-05 | tr '\n' ' ')" = '09:00-10:00 11:00-15:00 16:00-18:00 ' ] || { echo "free intervals of a day with two bookings"; fail=1; }
e=$(mktemp); printf '# h\n' > "$e"
[ "$(BOOKINGS=$e bash src/free.sh aoi 2026-01-05)" = '09:00-18:00' ] || { echo "free interval of a day without bookings"; fail=1; }
rm -f "$t" "$e"; exit $fail

